	(68164,1,00000000,00000000,2,NULL,NULL,NULL,20127,'Der Objektivismus als Kunstrichtung wurde 1985 durch den Künstler Bodo Sperling begründet. Zentraler Kern des Objektivismus ist die Dokumentation von Raumzeit. ','Objektivismus',NULL,NULL),
	(68165,1,00000000,00000000,2,NULL,'Objektivismus',NULL,20127,'Grundlage des Objektivismus ist die Annahme einer objektiven (im Sinne von „vom Bewusstsein unabhängigen“) Realität, die der Verstand mit den „richtigen“ Methoden (Beobachtung, Formen von Begriffen, Logik, etc.) zu erkennen in der Lage sein soll.','Objektivismus (Bodo Sperling)',NULL,NULL),
	(68166,1,00000000,00000000,2,NULL,NULL,NULL,20127,'Bodo Sperling entwickelte 1994 eine Hypothese, die die Struktur unseres Universums und die Entstehung der Vielfalt aus der Singularität erklärt.\r\n','Diversity Generator Hypothese',NULL,NULL),
	(68167,1,00000000,00000000,2,NULL,'Paradiso',NULL,20127,'Künstlerisch prägend war seine fast tägliche Anwesenheit im Club Paradiso (Amsterdam), in dem Sperling mit Künstlern aus allen Teilen der Welt zusammen kam.','Paradiso (Amsterdam)',NULL,NULL),
	(68168,1,00000000,00000000,2,5,NULL,NULL,20127,'Funktion / Ästhetik\r\n','Ästhetik',NULL,NULL),
